mapper.select:
SELECT pa.id, pa.post_id, pa.post_type, COALESCE(cl.type, li.type, crn.type) AS postSubType, COALESCE(cl.user_id, li.user_id, crn.club_id) AS userId, COALESCE(cl.title, li.item_name, crn.title) AS title, COALESCE(cl.create_time, li.create_time, crn.create_time) AS createTime, COALESCE(u.userName, u3.userName, u2.userName) AS userName, pa.status, pa.audit_time, pa.audit_user_id, u4.userName AS auditUserName, pa.reason FROM post_audit pa LEFT JOIN confession_log cl ON pa.post_id = cl.id AND pa.post_type = 1 LEFT JOIN lost_item li ON pa.post_id = li.id AND pa.post_type = 2 LEFT JOIN club_recruitment_news crn ON pa.post_id = crn.id AND pa.post_type = 3 LEFT JOIN user u ON cl.user_id = u.id AND pa.post_type = 1 LEFT JOIN user u2 ON li.user_id = u2.id AND pa.post_type = 2 LEFT JOIN user u3 ON crn.club_id = u3.id AND pa.post_type = 3 LEFT JOIN user u4 ON pa.audit_user_id = u4.id
AND pa.id = #{id}
AND COALESCE(u.userName, u3.userName, u2.userName) LIKE CONCAT('%', #{userName}, '%')
AND pa.status = #{status}
AND pa.post_type = #{postType}
AND COALESCE(cl.create_time, li.create_time, crn.create_time) >= #{startTime}
AND COALESCE(cl.create_time, li.create_time, crn.create_time) <= #{endTime}
AND COALESCE(cl.type, li.type, crn.type) = #{postSubType}
AND COALESCE(cl.title, li.item_name, crn.title) LIKE CONCAT('%', #{title}, '%')
